import pickle
x=y=z=0.0
e=0.0
obj='INIT'
objs={}
for line in open('text.gcode'):
    line=line.strip()
    if not line:
        continue
    code=line.split()[0]
    if code=='M486':
        for tok in line.split()[1:]:
            if tok[0]=='A':
                obj=tok[1:]
            elif tok[0]=='S':
                # S1 means object start, S-1 end; keep last A label active
                pass
        continue
    if code in ('G0','G1'):
        nx,ny,nz=x,y,z; ne=e
        for tok in line.split()[1:]:
            c=tok[0]; v=tok[1:]
            try: v=float(v)
            except: continue
            if c=='X': nx=v
            elif c=='Y': ny=v
            elif c=='Z': nz=v
            elif c=='E': ne=e+v
        if ne>e+1e-6:
            objs.setdefault(obj,[]).append((x,y,nx,ny,nz))
        x,y,z,e=nx,ny,nz,ne
for k,v in objs.items():
    xs=[s[0] for s in v]+[s[2] for s in v]
    ys=[s[1] for s in v]+[s[3] for s in v]
    zs=[s[4] for s in v]
    print(k, 'nseg=',len(v), 'X[%.1f,%.1f]'%(min(xs),max(xs)), 'Y[%.1f,%.1f]'%(min(ys),max(ys)), 'Z[%.2f,%.2f]'%(min(zs),max(zs)))
pickle.dump(objs,open('objs.pkl','wb'))
