import sys
fn=sys.argv[1] if len(sys.argv)>1 else 'sB.txt'
g=open(fn).read().split('\n')
g=[r.ljust(max(len(x) for x in g)) for r in g]
H=len(g);W=len(g[0])
seen=[[False]*W for _ in range(H)]
comps=[]
from collections import deque
for r in range(H):
    for c in range(W):
        if g[r][c]=='#' and not seen[r][c]:
            q=deque([(r,c)]);seen[r][c]=True;cells=[]
            while q:
                rr,cc=q.popleft();cells.append((rr,cc))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]=='#':
                            seen[nr][nc]=True;q.append((nr,nc))
            if len(cells)>=15:
                rs=[a for a,b in cells];cs=[b for a,b in cells]
                comps.append((min(cs),max(cs),min(rs),max(rs),len(cells),cells))
comps.sort(key=lambda t:t[0])
print('file',fn,'components',len(comps))
for i,(c0,c1,r0,r1,n,cells) in enumerate(comps):
    print('=== comp %d  x[%d-%d] w=%d h=%d cells=%d ==='%(i,c0,c1,c1-c0+1,r1-r0+1,n))
